{
  "title": "Discussion about working abroad in Slovakia, Austria and language requirements",
  "topics": [
    {
      "id": "expat-locations",
      "title": "People living or who have lived abroad",
      "claims": [
        {
          "text": "Some participants live in or have lived in Slovakia, Austria, Poland, and Austria since 2025.",
          "evidence": [1, 3, 12, 13, 49, 54]
        },
        {
          "text": "One participant has been in Austria since November 2025.",
          "evidence": [49]
        }
      ]
    },
    {
      "id": "job-search-abroad",
      "title": "Finding jobs abroad and application experience",
      "claims": [
        {
          "text": "Finding a job abroad was hard but the speaker succeeded within two months.",
          "evidence": [16, 17]
        },
        {
          "text": "LinkedIn was recommended as a job search platform.",
          "evidence": [18]
        },
        {
          "text": "The speaker sent about 100 applications and got only three interviews.",
          "evidence": [21, 22]
        },
        {
          "text": "Most job postings require local language proficiency (about 95%).",
          "evidence": [26]
        },
        {
          "text": "There are cases where candidates with little language knowledge are still hired.",
          "evidence": [29]
        },
        {
          "text": "Higher education rarely matters for hiring decisions.",
          "evidence": [32]
        },
        {
          "text": "Salary for the speaker’s position was low, comparable to minimum wage.",
          "evidence": [37]
        },
        {
          "text": "Employers often ask for B2 language level, sometimes B1, but certificates are rarely required.",
          "evidence": [46]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language expectations in the job market",
      "claims": [
        {
          "text": "German is the primary language spoken in Austria, but English is also used.",
          "evidence": [14, 15]
        },
        {
          "text": "Many companies list local language as a requirement, but some accept English.",
          "evidence": [15, 46]
        },
        {
          "text": "The speaker is learning the local language because of daily discomfort.",
          "evidence": [47]
        }
      ]
    },
    {
      "id": "personal-experiences",
      "title": "Personal anecdotes about living abroad",
      "claims": [
        {
          "text": "One participant feels less confident speaking English outside of work.",
          "evidence": [51, 52]
        },
        {
          "text": "Attending international events makes English usage easier.",
          "evidence": [55]
        },
        {
          "text": "A partner living in Austria for over 10 years is skeptical about the country’s future.",
          "evidence": [60]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Does anyone work for an Austrian company?",
      "evidence": [9]
    },
    {
      "text": "What is the typical salary range for junior positions abroad?",
      "evidence": [34]
    },
    {
      "text": "Will you stay in Austria or consider moving elsewhere?",
      "evidence": [58]
    }
  ]
}
